import{f as a,o as e,c as o,a4 as l}from"./chunks/framework.6QvN0vQS.js";const T=JSON.parse('{"title":"Casos de prueba de aceptación — T12 SRV — Fichas verticales por servicio · Parte 2 (DEC-073)","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/20-casos-prueba/T12-SRV-fichas-verticales-servicios-parte2.md","filePath":"entregables-analisis-diseno/20-casos-prueba/T12-SRV-fichas-verticales-servicios-parte2.md","lastUpdated":null}'),n={name:"entregables-analisis-diseno/20-casos-prueba/T12-SRV-fichas-verticales-servicios-parte2.md"};function c(r,i,s,t,d,u){return e(),o("div",null,[...i[0]||(i[0]=[l('<h1 id="casos-de-prueba-de-aceptacion-—-t12-srv-—-fichas-verticales-por-servicio-·-parte-2-dec-073" tabindex="-1">Casos de prueba de aceptación — T12 SRV — Fichas verticales por servicio · Parte 2 (DEC-073) <a class="header-anchor" href="#casos-de-prueba-de-aceptacion-—-t12-srv-—-fichas-verticales-por-servicio-·-parte-2-dec-073" aria-label="Permalink to &quot;Casos de prueba de aceptación — T12 SRV — Fichas verticales por servicio · Parte 2 (DEC-073)&quot;">​</a></h1><p>Parte de <a href="./../20-casos-prueba"><code>20-casos-prueba.md</code></a> (artefacto 9.2). Fuente: <a href="./../../especificacion/anexos/T12-SRV-fichas-verticales-servicios-parte2"><code>T12-SRV-fichas-verticales-servicios-parte2.md</code></a> (solo lectura). Generado por <code>_trabajo/gen_casos_prueba.py</code> y revisado; ante diferencias prevalece el anexo.</p><p>Resumen: 0 CP de requisitos funcionales, 58 CP de escenarios ESC y 0 CP de casos de uso CU.</p><p>Convenciones: el formato Dado / Cuando / Entonces sigue <code>07-estrategia-pruebas.md</code> §13; la ola de un CP de RF es la del prompt que lo implementa en <code>03</code> (prevalece sobre la columna del anexo); la de un CP de escenario es la última ola de los RF que cita o la que el escenario declara. Prioridad Extensión del anexo se agrupa como Estándar. Todos los datos son ficticios (TEN-001, TEN-002 y semillas del §18 del anexo).</p><h2 id="_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" tabindex="-1">2. Casos por escenario y criterio de aceptación con ID <a class="header-anchor" href="#_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" aria-label="Permalink to &quot;2. Casos por escenario y criterio de aceptación con ID&quot;">​</a></h2><p><strong>CP-SRV-5059 — ESC-T12-OBR-01. Se aprueba el prorrateo por metros de frente</strong></p><ul><li>Cubre: ESC-T12-OBR-01; relacionados: CU-TEC-09; T12 §7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OBR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado OBR-DEMO-01 de ARS 1.000.000 con base aprobada y frentistas de 10, 20, 30 y 40 m en TEN-001</li><li>Cuando se aprueba el prorrateo por metros de frente</li><li>Entonces se publica <code>tec.levy.approved</code> con ARS 100.000, 200.000, 300.000 y 400.000 y la suma es exactamente ARS 1.000.000 (CU-TEC-09).</li></ul><p><strong>CP-SRV-5060 — ESC-T12-OBR-02. Corre <code>tar:calcular-lote</code> y se emite el lote</strong></p><ul><li>Cubre: ESC-T12-OBR-02; T12 §7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OBR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el contrato del frentista de 20 m con plan de 10 cuotas</li><li>Cuando corre <code>tar:calcular-lote</code> y se emite el lote</li><li>Entonces la factura lleva &quot;Cuota 1/10&quot; por ARS 20.000, el plan pasa a 1 cuota facturada y, al anular la factura (EVT-FAC-08), vuelve a 0.</li></ul><p><strong>CP-SRV-5061 — ESC-T12-OBR-03. Se calcula la cuota 10</strong></p><ul><li>Cubre: ESC-T12-OBR-03; T12 §7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OBR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el mismo contrato con 9 cuotas facturadas y ARS 0,03 de redondeo acumulado</li><li>Cuando se calcula la cuota 10</li><li>Entonces cobra el saldo exacto y, tras emitirla, JOB-CAT-12 pasa el contrato a <code>terminated</code>.</li></ul><p><strong>CP-SRV-5062 — ESC-T12-OBR-04. (error) se calcula</strong></p><ul><li>Cubre: ESC-T12-OBR-04; T12 §7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OBR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un contrato tipo 17 de pavimento sin inmueble asociado</li><li>Cuando se calcula</li><li>Entonces el renglón falla con <code>TAR-E-WORKS-PROPERTY</code> en formato RFC 9457 y el contrato queda en la bandeja de excepciones del lote sin emitir factura.</li></ul><p><strong>CP-SRV-5063 — ESC-T12-OBR-05. (error) el responsable intenta aprobar el prorrateo en PAN-TEC-40</strong></p><ul><li>Cubre: ESC-T12-OBR-05; RN-TEC-093; T12 §7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OBR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado OBR-DEMO-02 sin base aprobada adjunta</li><li>Cuando el responsable intenta aprobar el prorrateo en PAN-TEC-40</li><li>Entonces recibe 422 y no se crea ningún contrato tipo 17 (RN-TEC-093).</li></ul><p><strong>CP-SRV-5064 — ESC-T12-OBR-06. (aislamiento) consulta <code>GET /admin/tec/works/{id de OBR-DEMO-01}</code></strong></p><ul><li>Cubre: ESC-T12-OBR-06; T12 §7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha OBR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un usuario de TEN-002 con <code>tec.obras.gestionar</code> (antes <code>tec.work.manage</code>)</li><li>Cuando consulta <code>GET /admin/tec/works/{id de OBR-DEMO-01}</code></li><li>Entonces recibe 404 y no ve la obra ni sus beneficiarios.</li></ul><p><strong>CP-SRV-5065 — ESC-T12-OBR-07. Un operador pide la baja anticipada</strong></p><ul><li>Cubre: ESC-T12-OBR-07; RF-MOR-069; T12 §7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OBR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un frentista con 4 cuotas impagas y PRM-CAT-072 = <code>supervisor</code></li><li>Cuando un operador pide la baja anticipada</li><li>Entonces la acción exige aprobación de supervisor, emite la cancelación del saldo y no suspende ningún otro servicio de la cuenta (RF-MOR-069).</li></ul><p><strong>CP-SRV-5066 — ESC-T12-SEP-01. M04 calcula el período 10-2026 con API-SOC-006</strong></p><ul><li>Cubre: ESC-T12-SEP-01; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SEP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el contrato SOC-FAM de &quot;Ana Demo&quot; con 3 adherentes vigentes al 31-10-2026 y franquicia de 2</li><li>Cuando M04 calcula el período 10-2026 con API-SOC-006</li><li>Entonces cobra la cuota del grupo más 1 adherente excedente y REP-SOC-03 informa 1 adherente facturable.</li></ul><p><strong>CP-SRV-5067 — ESC-T12-SEP-02. Se solicita un sepelio con evento el 15-10-2026</strong></p><ul><li>Cubre: ESC-T12-SEP-02; relacionados: ESC-SOC-02; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SEP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un hijo dado de alta el 01-09-2026 con carencia de 90 días</li><li>Cuando se solicita un sepelio con evento el 15-10-2026</li><li>Entonces la verificación devuelve <code>notCovered</code> por carencia con opción de excepción (ESC-SOC-02).</li></ul><p><strong>CP-SRV-5068 — ESC-T12-SEP-03. M18 consume <code>per.person.deceased</code></strong></p><ul><li>Cubre: ESC-T12-SEP-03; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SEP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un adherente fallecido registrado en M01</li><li>Cuando M18 consume <code>per.person.deceased</code></li><li>Entonces el adherente queda <code>ended</code> con causa <code>death</code>, la ficha lo oculta (PRM-SOC-007) y la cuota del período siguiente baja en ese adherente.</li></ul><p><strong>CP-SRV-5069 — ESC-T12-SEP-04. El mismo usuario que lo creó intenta aprobarlo</strong></p><ul><li>Cubre: ESC-T12-SEP-04; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SEP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un subsidio por ARS 300.000 con dos beneficiarios al 50 %</li><li>Cuando el mismo usuario que lo creó intenta aprobarlo</li><li>Entonces se rechaza; cuando lo aprueba otro usuario, entonces se publica EVT-SOC-04 y M14 emite la orden de pago.</li></ul><p><strong>CP-SRV-5070 — ESC-T12-SEP-05. (error) se da de alta un hijo de 25 años con <code>Idempotency-Key</code></strong></p><ul><li>Cubre: ESC-T12-SEP-05; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: integración</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SEP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un plan con edad máxima 21 para hijos</li><li>Cuando se da de alta un hijo de 25 años con <code>Idempotency-Key</code></li><li>Entonces la API responde 422 RFC 9457 con motivo &quot;edad fuera de rango&quot; y reenviar la misma clave no crea un adherente.</li></ul><p><strong>CP-SRV-5071 — ESC-T12-SEP-06. (aislamiento) consulta <code>/api/admin/soc/contracts/{contrato de Ana Demo}/dependents</code></strong></p><ul><li>Cubre: ESC-T12-SEP-06; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha SEP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un operador de TEN-002 con <code>soc.adherentes.ver</code></li><li>Cuando consulta <code>/api/admin/soc/contracts/{contrato de Ana Demo}/dependents</code></li><li>Entonces recibe 404.</li></ul><p><strong>CP-SRV-5072 — ESC-T12-SEP-07. Se activa un contrato ELE nuevo</strong></p><ul><li>Cubre: ESC-T12-SEP-07; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SEP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado PAR-DEMO-001 en modo <code>propose</code></li><li>Cuando se activa un contrato ELE nuevo</li><li>Entonces queda una propuesta de alta de SEP pendiente de consentimiento y no se crea contrato ni cargo hasta aceptarla (DEC-023).</li></ul><p><strong>CP-SRV-5073 — ESC-T12-CEM-01. Dos operadores la reservan al mismo tiempo</strong></p><ul><li>Cubre: ESC-T12-CEM-01; relacionados: ESC-SOC-07; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CEM (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado PAR-DEMO-001 disponible en &quot;Parque Demo&quot;</li><li>Cuando dos operadores la reservan al mismo tiempo</li><li>Entonces una reserva se confirma y la otra recibe <code>soc.unit.notAvailable</code> (ESC-SOC-07).</li></ul><p><strong>CP-SRV-5074 — ESC-T12-CEM-02. Corre JOB-SOC-04</strong></p><ul><li>Cubre: ESC-T12-CEM-02; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CEM (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado una reserva de PAR-DEMO-001 creada hace 8 días sin formalizar y PRM-SOC-014 = 7</li><li>Cuando corre JOB-SOC-04</li><li>Entonces la unidad vuelve a disponible y queda el evento de liberación.</li></ul><p><strong>CP-SRV-5075 — ESC-T12-CEM-03. Corre <code>mor:evaluar-mora</code></strong></p><ul><li>Cubre: ESC-T12-CEM-03; relacionados: ESC-SOC-05; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CEM (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un derecho formalizado con plan CEM-PAR de 24 cuotas de ARS 50.000 y 3 cuotas de mantenimiento impagas</li><li>Cuando corre <code>mor:evaluar-mora</code></li><li>Entonces no se crea orden de corte de otros servicios, el derecho y la ocupación no cambian y REP-SOC-10 muestra el saldo (ESC-SOC-05).</li></ul><p><strong>CP-SRV-5076 — ESC-T12-CEM-04. (error) se intenta registrar como realizada desde PAN-SOC-35</strong></p><ul><li>Cubre: ESC-T12-CEM-04; relacionados: ESC-SOC-08; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CEM (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado una inhumación solicitada por un tercero no autorizado</li><li>Cuando se intenta registrar como realizada desde PAN-SOC-35</li><li>Entonces se rechaza con <code>soc.act.unauthorized</code> (ESC-SOC-08).</li></ul><p><strong>CP-SRV-5077 — ESC-T12-CEM-05. Cambia el pagador a otro familiar</strong></p><ul><li>Cubre: ESC-T12-CEM-05; relacionados: ESC-SOC-06; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CEM (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un derecho con un fallecido inhumado</li><li>Cuando cambia el pagador a otro familiar</li><li>Entonces titular y ocupación no cambian y la próxima cuota sale a nombre del nuevo pagador (ESC-SOC-06).</li></ul><p><strong>CP-SRV-5078 — ESC-T12-CEM-06. (aislamiento) se consulta <code>/api/public/&amp;lt;slug de TEN-002&gt;/soc/cemetery/search</code> con el nombre de un difunto de TEN-001</strong></p><ul><li>Cubre: ESC-T12-CEM-06; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha CEM (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado PRM-SOC-050 = <code>true</code> en TEN-001 y <code>false</code> en TEN-002</li><li>Cuando se consulta <code>/api/public/&amp;lt;slug de TEN-002&gt;/soc/cemetery/search</code> con el nombre de un difunto de TEN-001</li><li>Entonces la respuesta está vacía o es 404 y nunca muestra datos de TEN-001.</li></ul><p><strong>CP-SRV-5079 — ESC-T12-SAN-01. Se cierra SAN-DEM-001</strong></p><ul><li>Cubre: ESC-T12-SAN-01; relacionados: ESC-SOC-09; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAN (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado CONV-SAN-DEMO financiado por la cooperativa y BEN-DEMO-001 vigente</li><li>Cuando se cierra SAN-DEM-001</li><li>Entonces no se genera comprobante al paciente y JOB-SOC-11 registra el costo del convenio del período (ESC-SOC-09).</li></ul><p><strong>CP-SRV-5080 — ESC-T12-SAN-02. (error) un administrador intenta crear un concepto facturable de tipo &quot;unidad de sangre&quot;</strong></p><ul><li>Cubre: ESC-T12-SAN-02; RF-SOC-067; T12 §7</li><li>Ola: O10 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAN (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el catálogo del servicio SAN</li><li>Cuando un administrador intenta crear un concepto facturable de tipo &quot;unidad de sangre&quot;</li><li>Entonces M02 lo rechaza con error RFC 9457 (RF-SOC-067).</li></ul><p><strong>CP-SRV-5081 — ESC-T12-SAN-03. Se registra una solicitud de sangre</strong></p><ul><li>Cubre: ESC-T12-SAN-03; RF-SOC-036; T12 §7</li><li>Ola: O10 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAN (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el titular de BEN-DEMO-001 con ARS 15.000 vencidos en otro servicio</li><li>Cuando se registra una solicitud de sangre</li><li>Entonces queda &quot;en gestión&quot; con advertencia y no es rechazada (RF-SOC-036).</li></ul><p><strong>CP-SRV-5082 — ESC-T12-SAN-04. (permiso) consulta solicitudes de banco de sangre</strong></p><ul><li>Cubre: ESC-T12-SAN-04; relacionados: ESC-SOC-11; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha SAN (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un supervisor de Agua de TEN-001</li><li>Cuando consulta solicitudes de banco de sangre</li><li>Entonces recibe 403 y no aparecen en la búsqueda global (ESC-SOC-11).</li></ul><p><strong>CP-SRV-5083 — ESC-T12-SAN-05. (aislamiento) pide <code>/api/admin/soc/blood-requests/{id de SAN-DEM-001}</code></strong></p><ul><li>Cubre: ESC-T12-SAN-05; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha SAN (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un operador de TEN-002 con <code>soc.sangre.ver</code></li><li>Cuando pide <code>/api/admin/soc/blood-requests/{id de SAN-DEM-001}</code></li><li>Entonces recibe 404.</li></ul><p><strong>CP-SRV-5084 — ESC-T12-SAN-06. Se inspecciona el esquema</strong></p><ul><li>Cubre: ESC-T12-SAN-06; relacionados: ESC-SOC-10; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAN (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el modelo de solicitudes de banco de sangre de M18</li><li>Cuando se inspecciona el esquema</li><li>Entonces no existen campos de grupo sanguíneo, diagnóstico ni compatibilidad (ESC-SOC-10).</li></ul><p><strong>CP-SRV-5085 — ESC-T12-SAL-01. El chofer lo finaliza en PAN-SOC-34 y el responsable lo cierra</strong></p><ul><li>Cubre: ESC-T12-SAL-01; RF-SOC-080; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAL (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un viaje no cubierto de 120 km con tarifa ARS 900 por km</li><li>Cuando el chofer lo finaliza en PAN-SOC-34 y el responsable lo cierra</li><li>Entonces se publica <code>soc.trip.completed</code> y M05 recibe un ítem facturable de ARS 108.000 (RF-SOC-080).</li></ul><p><strong>CP-SRV-5086 — ESC-T12-SAL-02. Se verifica una nueva solicitud</strong></p><ul><li>Cubre: ESC-T12-SAL-02; RF-SOC-035; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAL (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un plan con tope anual de 2 traslados y uno ya usado</li><li>Cuando se verifica una nueva solicitud</li><li>Entonces la cobertura informa 1 disponible y el viaje queda cubierto (RF-SOC-035).</li></ul><p><strong>CP-SRV-5087 — ESC-T12-SAL-03. Se registra</strong></p><ul><li>Cubre: ESC-T12-SAL-03; relacionados: ESC-SOC-22; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAL (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado una solicitud marcada emergencia</li><li>Cuando se registra</li><li>Entonces queda <code>derived</code>, muestra la derivación de PRM-SOC-048 y no se agenda (ESC-SOC-22).</li></ul><p><strong>CP-SRV-5088 — ESC-T12-SAL-04. (error) se lo asigna a un traslado</strong></p><ul><li>Cubre: ESC-T12-SAL-04; relacionados: ESC-SOC-18; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAL (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado AMB-01 con seguro vencido</li><li>Cuando se lo asigna a un traslado</li><li>Entonces la asignación falla con <code>soc.vehicle.unfit</code> (ESC-SOC-18).</li></ul><p><strong>CP-SRV-5089 — ESC-T12-SAL-05. (permiso) abre un traslado y exporta el informe</strong></p><ul><li>Cubre: ESC-T12-SAL-05; relacionados: ESC-SOC-12; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha SAL (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un operador sin <code>soc.datosSensibles.ver</code></li><li>Cuando abre un traslado y exporta el informe</li><li>Entonces el motivo aparece enmascarado y no se exporta (ESC-SOC-12).</li></ul><p><strong>CP-SRV-5090 — ESC-T12-SAL-06. (aislamiento) consulta un viaje de TEN-001 por id</strong></p><ul><li>Cubre: ESC-T12-SAL-06; relacionados: ESC-SOC-14; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha SAL (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un usuario de TEN-002</li><li>Cuando consulta un viaje de TEN-001 por id</li><li>Entonces recibe 404 (ESC-SOC-14).</li></ul><p><strong>CP-SRV-5091 — ESC-T12-VIV-01. M04 calcula la cuota</strong></p><ul><li>Cubre: ESC-T12-VIV-01; relacionados: ESC-SOC-15; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha VIV (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado &quot;Dúplex 2D&quot; a ARS 40.000.000, adjudicada, mínimo 1 % y 99,5 % facturado</li><li>Cuando M04 calcula la cuota</li><li>Entonces el aporte es 0,5 % = ARS 200.000 (ESC-SOC-15).</li></ul><p><strong>CP-SRV-5092 — ESC-T12-VIV-02. Se anula la factura</strong></p><ul><li>Cubre: ESC-T12-VIV-02; relacionados: ESC-SOC-16, ESC-SOC-23; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha VIV (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado una cuota de 1 % emitida (ARS 400.000)</li><li>Cuando se anula la factura</li><li>Entonces <code>pctBilled</code> baja 1 punto y el evento repetido no lo baja dos veces (ESC-SOC-16, ESC-SOC-23).</li></ul><p><strong>CP-SRV-5093 — ESC-T12-VIV-03. (error) se inscribe un segundo plan</strong></p><ul><li>Cubre: ESC-T12-VIV-03; relacionados: ESC-SOC-17; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha VIV (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado una cuenta con un plan de vivienda</li><li>Cuando se inscribe un segundo plan</li><li>Entonces se rechaza con <code>soc.housing.secondPlan</code> (ESC-SOC-17).</li></ul><p><strong>CP-SRV-5094 — ESC-T12-VIV-04. Se rescinde el plan conectado con aprobación</strong></p><ul><li>Cubre: ESC-T12-VIV-04; RF-SOC-108; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha VIV (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado aportes por ARS 4.000.000 y comisión de rescisión 10 %</li><li>Cuando se rescinde el plan conectado con aprobación</li><li>Entonces se calcula ARS 400.000 de comisión y el saldo a devolver o compensar (RF-SOC-108).</li></ul><p><strong>CP-SRV-5095 — ESC-T12-VIV-05. (separación de tareas) intenta aprobar el certificado</strong></p><ul><li>Cubre: ESC-T12-VIV-05; relacionados: ESC-SOC-13; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha VIV (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el técnico que cargó el progreso</li><li>Cuando intenta aprobar el certificado</li><li>Entonces se rechaza (ESC-SOC-13).</li></ul><p><strong>CP-SRV-5096 — ESC-T12-VIV-06. (aislamiento) pide <code>/api/admin/soc/housing-units/{id de TEN-001}</code></strong></p><ul><li>Cubre: ESC-T12-VIV-06; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha VIV (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un usuario de TEN-002 con <code>soc.vivienda.ver</code></li><li>Cuando pide <code>/api/admin/soc/housing-units/{id de TEN-001}</code></li><li>Entonces recibe 404.</li></ul><p><strong>CP-SRV-5097 — ESC-T12-VIV-07. Se factura el período 07-2026 el 05-10-2026</strong></p><ul><li>Cubre: ESC-T12-VIV-07; RF-SOC-086; RN-SOC-032; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha VIV (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado precios de &quot;Dúplex 2D&quot; del 01-03-2026 y del 01-09-2026</li><li>Cuando se factura el período 07-2026 el 05-10-2026</li><li>Entonces se usa el precio del 01-03-2026 (RF-SOC-086, RN-SOC-032).</li></ul><p><strong>CP-SRV-5098 — ESC-T12-TAS-01. Se emite la factura de energía de ARS 20.000 de un socio residencial</strong></p><ul><li>Cubre: ESC-T12-TAS-01; T12 §7</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha TAS (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el convenio &quot;Municipalidad Demo — Tasa hospital&quot; vigente por ARS 1.000 por factura</li><li>Cuando se emite la factura de energía de ARS 20.000 de un socio residencial</li><li>Entonces el PDF muestra el bloque de terceros con ARS 1.000, el tributo va con Id 3 y el asiento acredita el pasivo del convenio.</li></ul><p><strong>CP-SRV-5099 — ESC-T12-TAS-02. El socio paga ARS 10.500</strong></p><ul><li>Cubre: ESC-T12-TAS-02; RF-FIS-138; T12 §7</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha TAS (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado esa factura de ARS 21.000 (ARS 1.000 de terceros)</li><li>Cuando el socio paga ARS 10.500</li><li>Entonces se imputan ARS 500 al tercero por prorrata y EVT-FIS-16 informa ese importe (RF-FIS-138).</li></ul><p><strong>CP-SRV-5100 — ESC-T12-TAS-03. (error) corre el lote</strong></p><ul><li>Cubre: ESC-T12-TAS-03; RF-FAC-120; T12 §7</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha TAS (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un ítem &quot;Tasa de bomberos&quot; sin convenio vigente</li><li>Cuando corre el lote</li><li>Entonces el ítem queda en la bandeja de excepciones &quot;Concepto de terceros sin convenio&quot; y la factura sale sin ese ítem (RF-FAC-120).</li></ul><p><strong>CP-SRV-5101 — ESC-T12-TAS-04. Corre JOB-FIS-15 y se aprueba la rendición</strong></p><ul><li>Cubre: ESC-T12-TAS-04; T12 §7</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha TAS (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado cobros imputados al tercero por ARS 50.000 en el período y comisión 2 %</li><li>Cuando corre JOB-FIS-15 y se aprueba la rendición</li><li>Entonces el neto a rendir es ARS 49.000, M14 recibe la orden de pago y REP-FIS-012 cuadra.</li></ul><p><strong>CP-SRV-5102 — ESC-T12-TAS-05. (error) el cajero intenta anular el cobro</strong></p><ul><li>Cubre: ESC-T12-TAS-05; RN-COB-073; T12 §7</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha TAS (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un comprobante de &quot;Ente Demo Agua&quot; cobrado en caja y ya rendido</li><li>Cuando el cajero intenta anular el cobro</li><li>Entonces se rechaza (RN-COB-073).</li></ul><p><strong>CP-SRV-5103 — ESC-T12-TAS-06. (aislamiento) lista convenios</strong></p><ul><li>Cubre: ESC-T12-TAS-06; T12 §7</li><li>Ola: O8 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha TAS (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un usuario de TEN-002 con <code>fis.terceros.configurar</code></li><li>Cuando lista convenios</li><li>Entonces no ve el convenio de TEN-001 y su id devuelve 404.</li></ul><p><strong>CP-SRV-5104 — ESC-T12-TAS-07. (error) se valida la importación</strong></p><ul><li>Cubre: ESC-T12-TAS-07; RF-FAC-121; T12 §7</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha TAS (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un archivo IAL de alumbrado con un suministro inexistente</li><li>Cuando se valida la importación</li><li>Entonces esa fila se rechaza con &quot;CUENTA INEXISTENTE&quot; y las demás quedan listas para confirmar (RF-FAC-121).</li></ul><p><strong>CP-SRV-5105 — ESC-T12-CAP-01. Se emite la factura de Internet de ARS 22.000</strong></p><ul><li>Cubre: ESC-T12-CAP-01; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CAP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado PRM-INS-017 = <code>inServiceInvoice</code> y un concepto capitalizable de ARS 1.000</li><li>Cuando se emite la factura de Internet de ARS 22.000</li><li>Entonces el comprobante muestra &quot;Cuota social ARS 1.000&quot; en renglón propio con leyenda y se registra un movimiento <code>billed</code> de ARS 1.000 (DEC-061).</li></ul><p><strong>CP-SRV-5106 — ESC-T12-CAP-02. Se confirma un pago de ARS 9.200 (40 %)</strong></p><ul><li>Cubre: ESC-T12-CAP-02; RF-INS-035; T12 §7</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CAP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado esa factura de ARS 23.000</li><li>Cuando se confirma un pago de ARS 9.200 (40 %)</li><li>Entonces se integran ARS 400 y el asiento de integración se genera en M15 (RF-INS-035).</li></ul><p><strong>CP-SRV-5107 — ESC-T12-CAP-03. Se anula (EVT-FAC-08)</strong></p><ul><li>Cubre: ESC-T12-CAP-03; RN-INS-019; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CAP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado la factura con capital integrado parcialmente</li><li>Cuando se anula (EVT-FAC-08)</li><li>Entonces se crean contramovimientos vinculados, el saldo vuelve al previo y ningún movimiento se borra (RN-INS-019).</li></ul><p><strong>CP-SRV-5108 — ESC-T12-CAP-04. (error) se intenta preparar un lote sobre el mismo universo</strong></p><ul><li>Cubre: ESC-T12-CAP-04; RF-FAC-017, RF-INS-044; T12 §7</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CAP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado JOB-INS-01 en curso sobre el universo &quot;Residencial Centro&quot;</li><li>Cuando se intenta preparar un lote sobre el mismo universo</li><li>Entonces el lote se bloquea con motivo de registración de capital en curso; un lote de otro universo no se bloquea (RF-FAC-017, RF-INS-044).</li></ul><p><strong>CP-SRV-5109 — ESC-T12-CAP-05. Se reejecuta con la misma clave</strong></p><ul><li>Cubre: ESC-T12-CAP-05; RF-INS-038; T12 §7</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CAP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado JOB-INS-01 ejecutado sobre un lote</li><li>Cuando se reejecuta con la misma clave</li><li>Entonces no se duplican movimientos (RF-INS-038).</li></ul><p><strong>CP-SRV-5110 — ESC-T12-CAP-06. (aislamiento) consulta <code>/ins/asociados/{asociado de TEN-001}/capital</code></strong></p><ul><li>Cubre: ESC-T12-CAP-06; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha CAP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un usuario de TEN-002 con <code>ins.capital.ver</code></li><li>Cuando consulta <code>/ins/asociados/{asociado de TEN-001}/capital</code></li><li>Entonces recibe 404 y REP-INS-05 de TEN-002 no incluye importes de TEN-001.</li></ul><p><strong>CP-SRV-5111 — ESC-T12-CAP-07. (error) se registra un ajuste manual con fecha 30-10-2026</strong></p><ul><li>Cubre: ESC-T12-CAP-07; RF-INS-053; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha CAP (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un cierre de capital al 31-10-2026</li><li>Cuando se registra un ajuste manual con fecha 30-10-2026</li><li>Entonces se rechaza con <code>ins.capital.closed</code> (RF-INS-053).</li></ul><p><strong>CP-SRV-5112 — ESC-T12-OTR-01. Se presta a un asociado con depósito ARS 20.000 y plazo 30 días, y se devuelve a los 20 días</strong></p><ul><li>Cubre: ESC-T12-OTR-01; relacionados: CU-SOC-15; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OTR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado ORT-DEMO-01 disponible</li><li>Cuando se presta a un asociado con depósito ARS 20.000 y plazo 30 días, y se devuelve a los 20 días</li><li>Entonces el elemento pasa a limpieza o mantenimiento y no se presta hasta liberarlo (CU-SOC-15).</li></ul><p><strong>CP-SRV-5113 — ESC-T12-OTR-02. Corre JOB-SOC-10</strong></p><ul><li>Cubre: ESC-T12-OTR-02; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OTR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un préstamo con plazo vencido ayer</li><li>Cuando corre JOB-SOC-10</li><li>Entonces queda <code>overdue</code> y se genera el aviso; repetir el job no duplica el aviso.</li></ul><p><strong>CP-SRV-5114 — ESC-T12-OTR-03. (error) se registra un retiro de 10 litros con <code>Idempotency-Key</code></strong></p><ul><li>Cubre: ESC-T12-OTR-03; RF-SOC-114; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: integración</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OTR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un límite diario de 20 litros y 15 litros ya retirados hoy</li><li>Cuando se registra un retiro de 10 litros con <code>Idempotency-Key</code></li><li>Entonces se rechaza con 422 RFC 9457 y reenviar la misma clave devuelve el mismo rechazo (RF-SOC-114).</li></ul><p><strong>CP-SRV-5115 — ESC-T12-OTR-04. (error) se intenta crear un contrato</strong></p><ul><li>Cubre: ESC-T12-OTR-04; RN-SOC-052; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración y precarga de la ficha OTR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un servicio &quot;Seguro de vida&quot; en estado candidato</li><li>Cuando se intenta crear un contrato</li><li>Entonces M02 lo rechaza (RN-SOC-052).</li></ul><p><strong>CP-SRV-5116 — ESC-T12-OTR-05. (aislamiento) pide el préstamo de ORT-DEMO-01 de TEN-001</strong></p><ul><li>Cubre: ESC-T12-OTR-05; T12 §7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración y precarga de la ficha OTR (T12, sección 2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado un operador de TEN-002 con <code>soc.ortopedia.gestionar</code></li><li>Cuando pide el préstamo de ORT-DEMO-01 de TEN-001</li><li>Entonces recibe 404.</li></ul>',121)])])}const E=a(n,[["render",c]]);export{T as __pageData,E as default};
